import { useState, useRef, useCallback } from 'react';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  isStreaming?: boolean;
}

export function useStreamingChat(apiUrl: string) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const sendMessage = useCallback(async (prompt: string, tenantId: string) => {
    const userMsg: Message = { id: crypto.randomUUID(), role: 'user', content: prompt };
    const assistantId = crypto.randomUUID();
    const initialAssistantMsg: Message = { id: assistantId, role: 'assistant', content: '', isStreaming: true };

    setMessages((prev) => [...prev, userMsg, initialAssistantMsg]);
    setIsGenerating(true);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const response = await fetch(`${apiUrl}/api/chat/stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, query: prompt }),
        signal: controller.signal,
      });

      if (!response.ok || !response.body) {
        throw new Error(`HTTP error ${response.status}`);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let accumulatedContent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6).trim();
            if (data === '[DONE]') continue;

            try {
              const parsed = JSON.parse(data);
              if (parsed.token) {
                accumulatedContent += parsed.token;
                setMessages((prev) =>
                  prev.map((msg) =>
                    msg.id === assistantId
                      ? { ...msg, content: accumulatedContent }
                      : msg
                  )
                );
              }
            } catch {
              // Handle fragmented JSON chunks gracefully
            }
          }
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        console.error('Streaming error:', err);
      }
    } finally {
      setIsGenerating(false);
      setMessages((prev) =>
        prev.map((msg) => (msg.id === assistantId ? { ...msg, isStreaming: false } : msg))
      );
      abortControllerRef.current = null;
    }
  }, [apiUrl]);

  const stopGeneration = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setIsGenerating(false);
    }
  }, []);

  return { messages, isGenerating, sendMessage, stopGeneration };
}

import React, { useState } from 'react';

interface CitationBadgeProps {
  chunkId: string;
  documentTitle: string;
  excerpt: string;
  pageNumber?: number;
}

export const CitationBadge: React.FC<CitationBadgeProps> = ({
  chunkId,
  documentTitle,
  excerpt,
  pageNumber,
}) => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <span className="relative inline-block mx-1">
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="inline-flex items-center gap-1 px-1.5 py-0.5 text-xs font-medium rounded bg-accent-subtle text-accent-fg border border-accent hover:bg-accent hover:text-white transition-colors"
        aria-label={`Source citation: ${documentTitle}`}
        aria-expanded={isOpen}
      >
        📄 {documentTitle.slice(0, 16)}...
      </button>

      {isOpen && (
        <div className="absolute z-50 bottom-full mb-2 left-0 w-80 p-3 bg-canvas-overlay border border-border rounded-lg shadow-xl text-xs text-fg-default animate-fade-in">
          <div className="flex justify-between items-center mb-1 font-semibold text-accent-fg">
            <span>{documentTitle}</span>
            {pageNumber && <span className="text-fg-muted">p. {pageNumber}</span>}
          </div>
          <p className="italic text-fg-muted line-clamp-4 font-mono bg-canvas-subtle p-2 rounded">
            "{excerpt}"
          </p>
          <div className="mt-2 flex justify-end">
            <button
              type="button"
              onClick={() => setIsOpen(false)}
              className="text-xs text-fg-muted hover:text-fg-default underline"
            >
              Dismiss
            </button>
          </div>
        </div>
      )}
    </span>
  );
};
